UPDATE `basic_enum_type` SET `description` = '记录用户资料中的性别选项，用于信息维护和展示。' WHERE `enum_id` = 1 AND `workspace_id` = 1001 AND `enum_type` = 'sys_user_sex' AND `del_flag` = 0 AND (`description` IS NULL OR TRIM(`description`) = '');
